function spawnCar(){let lane=Math.floor(Math.random()*5),skin=Math.floor(Math.random()*colors.length),truck=Math.random()<.22,truckType=truck?(hasLongTruckSkin()&&Math.random()<.7?'allAboard':Math.random()<.5?'tanker':'trailer'):'';traffic.push({y:-.12,color:truckType==='allAboard'?'#d5a43a':colors[skin],skin,lane,truck,truckType})}
function pop(text){let el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1700)}
function updateSkill(){const el=document.getElementById('skillbar'),cooldownEl=document.getElementById('cooldownStatus'),active=Object.entries(skillTimers).filter(([,time])=>time>0).map(([type,time])=>`${skillNames[type]} ${time.toFixed(1)}s`),cooldowns=[];if(turboTime>0)active.push(`TURBO ${turboTime.toFixed(1)}s`);if(wetGripTimer>0)active.push(`LOW GRIP ${wetGripTimer.toFixed(1)}s`);if(skillsOwned.includes('secondChance')&&secondChanceUsed<secondChanceLimit())active.push('SECOND CHANCE · AUTO SAVE READY');if(handCooldown>0)cooldowns.push(`THE HAND ${handCooldown.toFixed(1)}s`);if(turboCooldown>0)cooldowns.push(`TURBO ${turboCooldown.toFixed(1)}s`);for(const [type,label] of [['sharpWay','SHARP WAY'],['cutTime','CUT THE TIME']])if(skillCooldowns[type]>0&&skillTimers[type]<=0)cooldowns.push(`${label} ${skillCooldowns[type].toFixed(1)}s`);if(keys.z)active.push(driftContinuous>0?`DRIFT · ${driftContinuous.toFixed(1)}s`:'DRIFT · LOW GRIP');el.textContent=active.join('  ·  ');el.classList.toggle('active',active.length>0);cooldownEl.textContent=cooldowns.length?`COOLDOWN · ${cooldowns.join(' · ')}`:'';cooldownEl.classList.toggle('active',cooldowns.length>0);const full={filled:6,slow:8,berserker:12,sharpWay:4+skillBonusDuration(),cutTime:12+skillBonusDuration()},progress=Math.max(...Object.entries(skillTimers).map(([type,time])=>time/(full[type]||1)),turboTime/(turboDurations[upgrades.turbo-1]||1));el.style.setProperty('--fill',`${Math.max(0,Math.min(100,progress*100))}%`)}
function useSkill(type){const duration={filled:6,slow:8,berserker:12};skillTimers[type]=duration[type];pop(`${skillNames[type]} · ${duration[type]}s`);playSfx('pickup');updateSkill()}
function spawnPickup(){let lane=Math.floor(Math.random()*5),type=['filled','slow','berserker'][Math.floor(Math.random()*3)];pickups.push({lane,y:-.05,type})}
function showAchievement(title){const box=document.getElementById('achievementUnlock');document.getElementById('unlockName').textContent=title;box.classList.remove('show');void box.offsetWidth;box.classList.add('show');playSfx('unlock')}
function checkNuclearProgress(){if(runMode!=='nuclear')return;const before=nuclearBest;nuclearBest=Math.max(nuclearBest,Math.floor(score));if(score>=4000)awardSpecial('radiation-comfortable','radiation sound is so comfortable');if(score>=12000)awardSpecial('ninety-nine','99% ?');if(score>=50000)awardSpecial('eye-hand','why there is eye on my hand !?');if(before<70000&&nuclearBest>=70000){syncSkinSelect();pop('TANK UNLOCKED')}if(before<99999&&nuclearBest>=99999){syncSkinSelect();pop('BTR-80 UNLOCKED')}}
