function checkPrizeCollector(){const id='prize-collector';if(specialAchieved.includes(id))return;const allDistances=milestones.every(([distance])=>achieved.includes(distance)),allSpecial=specialChallenges.filter(([specialId])=>specialId!==id).every(([specialId])=>specialAchieved.includes(specialId));if(allDistances&&allSpecial){specialAchieved.push(id);localStorage.setItem('nsSpecialAch',JSON.stringify(specialAchieved));pop('ACHIEVEMENT · Prize Collector');showAchievement('Prize Collector')}}
