 XW_ENGINES.forEach((x,i)=>{const flick=.82+.18*Math.sin(t/38+i*1.9),len=(boost?36:15)*flick,g=ctx.createLinearGradient(0,100,0,100+len);g.addColorStop(0,boost?'#ffffff':'#fff3c4');g.addColorStop(.4,boost?'#6fd8ff':'#ff9a3c');g.addColorStop(1,boost?'rgba(40,120,255,0)':'rgba(255,61,46,0)');ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(x-3.4,100);ctx.lineTo(x+3.4,100);ctx.lineTo(x,100+len);ctx.closePath();ctx.fill();ctx.save();ctx.globalAlpha=.5*flick;ctx.fillStyle=boost?'#58eaff':'#ff7a3d';ctx.beginPath();ctx.arc(x,101,5.4,0,Math.PI*2);ctx.fill();ctx.restore()});
 ctx.strokeStyle='rgba(10,18,24,.55)';ctx.lineWidth=.7;ctx.lineJoin='round';
