function redeemCode(){const input=document.getElementById('redeemCodeInput'),message=document.getElementById('redeemMessage'),code=input.value.trim().toUpperCase().replace(/[\u2018\u2019\u02BC]/g,"'").replace(/\s+/g,' ');if(!code){message.textContent='Enter a code first.';message.className='redeem-message error';return}if(!Object.prototype.hasOwnProperty.call(redeemRewards,code)){message.textContent='That code is not valid.';message.className='redeem-message error';return}if(redeemedCodes.includes(code)){message.textContent='You already redeemed that code.';message.className='redeem-message error';return}const reward=redeemRewards[code];if(reward.wipeAll){playing=false;for(const key of Object.keys(localStorage)){if(key.startsWith('ns')||key.startsWith('neonRoad'))localStorage.removeItem(key)}location.reload();return}redeemedCodes.push(code);if(reward.coins){coins=Math.max(0,coins+reward.coins);localStorage.setItem('nsCoins',coins);coinsEl.textContent=coins;const shopCoins=document.getElementById('shopCoins');if(shopCoins)shopCoins.textContent=coins}if(reward.unlockShip){syncSkinSelect();if(document.getElementById('shopmodal').classList.contains('open'))renderShop()}if(reward.unlockSkin){syncSkinSelect();document.getElementById('skin').value=skinColor;if(document.getElementById('shopmodal').classList.contains('open'))renderShop()}if(reward.berserkerNextRun)localStorage.setItem('nsBerserkerNextRun','5');if(reward.achievement&&!specialAchieved.includes(reward.achievement)){specialAchieved.push(reward.achievement);localStorage.setItem('nsSpecialAch',JSON.stringify(specialAchieved));renderAchievements()}if(reward.secretDriver){leaderRank=renderLeaderboard()}if(reward.deleteBest){best=0;localStorage.setItem('neonRoadBest',0);document.getElementById('best').textContent='0000';leaderRank=renderLeaderboard()}if(reward.unlockAll){if(reward.unlockSecretSkins)for(const skinCode of ['RAIN CHECK','GHOST LANE','NIGHTSHIFT','X-WING','ALL ABOARD'])if(!redeemedCodes.includes(skinCode))redeemedCodes.push(skinCode);if(reward.bestDistance){nuclearBest=Math.max(nuclearBest,reward.bestDistance);localStorage.setItem('nsNuclearBest',nuclearBest)}syncSkinSelect();upgrades={tires:maxLevels.tires,engine:maxLevels.engine,turbo:maxLevels.turbo};skillsOwned=['sharpWay','cutTime','theHand','secondChance'];achieved=milestones.map(([distance])=>distance);specialAchieved=specialChallenges.map(([id])=>id);syncSkinSelect();best=Math.max(best,reward.bestDistance||28500);localStorage.setItem('nsUpgrades',JSON.stringify(upgrades));localStorage.setItem('nsSkills',JSON.stringify(skillsOwned));localStorage.setItem('nsAch',JSON.stringify(achieved));localStorage.setItem('nsSpecialAch',JSON.stringify(specialAchieved));localStorage.setItem('neonRoadBest',best);document.getElementById('best').textContent=String(best).padStart(4,'0');renderAchievements();renderLeaderboard();if(document.getElementById('shopmodal').classList.contains('open'))renderShop()}localStorage.setItem('nsRedeemedCodes',JSON.stringify(redeemedCodes));checkCoinAchievementsSilently();renderAboutMessages();message.textContent='';message.className='redeem-message';input.value=''}
